    h, w = len(grid), len(grid[0])
    candidates = set()

    # Find uniform rectangles of at least 4x5 (or 5x4), the solid panels
    # encoded in this task. Each candidate is (color, top, bottom, left, right).
    for top in range(h):
        for bottom in range(top + 3, h):
            height = bottom - top + 1
            left = 0
            while left < w:
                color = grid[top][left]
                right = left + 1
                while right < w and all(grid[r][right] == color for r in range(top, bottom + 1)):
                    right += 1
                width = right - left
                if (height >= 4 and width >= 5) or (height >= 5 and width >= 4):
                    candidates.add((color, top, bottom, left, right - 1))
                left = right

    # Keep only maximal qualifying rectangles so subrectangles do not cause
    # partial or over-extended recoloring.
    maximal = []
    for rect in candidates:
        color, top, bottom, left, right = rect
        contained = any(
            color == other_color
            and other_top <= top and other_bottom >= bottom
            and other_left <= left and other_right >= right
            and rect != other
            for other in candidates
            for other_color, other_top, other_bottom, other_left, other_right in [other]
        )
        if not contained:
            maximal.append(rect)

    out = [row[:] for row in grid]
    for _, top, bottom, left, right in maximal:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = 4
    return out


